export const ROUND_SLOTS = ['H1', 'C1', 'H2', 'C2'];
export function archiveRound() {
  return ROUND_SLOTS.map(id => ARCHIVE.find(c => c.id === id));
}
export function specimenCards() {
  return ARCHIVE.slice();
}